begin;
create extension if not exists pgcrypto;
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,currency_code char(3) not null default 'SAR',created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.company_members(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in ('owner','admin','accountant','supervisor','cashier','staff','viewer')),is_active boolean not null default true,unique(company_id,user_id),unique(company_id,id));
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,code text not null,name text not null,is_default boolean not null default false,unique(company_id,id),unique(company_id,code));
create table if not exists public.cost_centers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid,code text not null,name text not null,parent_id uuid,unique(company_id,id),foreign key(company_id,branch_id) references public.branches(company_id,id),foreign key(company_id,parent_id) references public.cost_centers(company_id,id));
create table if not exists public.fiscal_periods(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,starts_on date not null,ends_on date not null,status text not null default 'open' check(status in ('open','closing','closed')),unique(company_id,id),check(ends_on>=starts_on));
create table if not exists public.accounts(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,parent_id uuid,code text not null,name text not null,account_type text not null check(account_type in ('asset','liability','equity','revenue','expense')),normal_balance text not null check(normal_balance in ('debit','credit')),level smallint not null check(level between 1 and 4),is_group boolean not null default false,unique(company_id,id),unique(company_id,code),foreign key(company_id,parent_id) references public.accounts(company_id,id),check(parent_id is not null or level=1));
create table if not exists public.parties(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,party_type text not null check(party_type in ('customer','supplier','both')),code text not null,name text not null,phone text,email text,credit_limit numeric(20,4) not null default 0,opening_balance numeric(20,4) not null default 0,unique(company_id,id),unique(company_id,code));
create table if not exists public.units(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,symbol text not null,unique(company_id,id),unique(company_id,symbol));
create table if not exists public.products(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,sku text not null,barcode text,name text not null,item_type text not null default 'product' check(item_type in ('product','service')),base_unit_id uuid,last_purchase_price numeric(20,4) not null default 0,sale_price numeric(20,4) not null default 0,alert_quantity numeric(20,4) not null default 0,track_inventory boolean not null default true,unique(company_id,id),unique(company_id,sku),foreign key(company_id,base_unit_id) references public.units(company_id,id),check(item_type<>'service' or track_inventory=false));
create unique index if not exists products_barcode_company on public.products(company_id,barcode) where barcode is not null and barcode<>'';
create table if not exists public.warehouses(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid,code text not null,name text not null,unique(company_id,id),foreign key(company_id,branch_id) references public.branches(company_id,id));
create table if not exists public.inventory_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null,warehouse_id uuid not null,product_id uuid not null,movement_type text not null,quantity_in numeric(20,4) not null default 0,quantity_out numeric(20,4) not null default 0,unit_cost numeric(20,4) not null default 0,occurred_at timestamptz not null default now(),foreign key(company_id,warehouse_id) references public.warehouses(company_id,id),foreign key(company_id,product_id) references public.products(company_id,id),check((quantity_in>0 and quantity_out=0) or (quantity_out>0 and quantity_in=0)));
create table if not exists public.cash_drawers(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid,code text not null,name text not null,unique(company_id,id),foreign key(company_id,branch_id) references public.branches(company_id,id));
create table if not exists public.payment_methods(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,code text not null,name text not null,method_type text not null check(method_type in ('cash','card','bank_transfer','credit','other')),account_id uuid,unique(company_id,id),foreign key(company_id,account_id) references public.accounts(company_id,id));
create table if not exists public.pos_shifts(id uuid primary key default gen_random_uuid(),company_id uuid not null,branch_id uuid not null,cash_drawer_id uuid not null,opened_by uuid not null references auth.users(id),opened_at timestamptz not null default now(),opening_amount numeric(20,4) not null default 0,closed_by uuid references auth.users(id),closed_at timestamptz,closing_amount numeric(20,4),status text not null default 'open' check(status in ('open','closed')),foreign key(company_id,branch_id) references public.branches(company_id,id),foreign key(company_id,cash_drawer_id) references public.cash_drawers(company_id,id),check((status='open' and closed_at is null) or (status='closed' and closed_at is not null)));
create unique index if not exists pos_one_open_shift_per_drawer on public.pos_shifts(company_id,cash_drawer_id) where status='open';
create table if not exists public.journal_entries(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),branch_id uuid,fiscal_period_id uuid,entry_no bigint generated always as identity,entry_date date not null default current_date,description text not null,status text not null default 'draft' check(status in ('draft','posted','reversed')),created_by uuid references auth.users(id),posted_by uuid references auth.users(id),posted_at timestamptz,unique(company_id,id),foreign key(company_id,branch_id) references public.branches(company_id,id),foreign key(company_id,fiscal_period_id) references public.fiscal_periods(company_id,id));
create table if not exists public.journal_lines(id uuid primary key default gen_random_uuid(),company_id uuid not null,journal_entry_id uuid not null,account_id uuid not null,cost_center_id uuid,debit numeric(20,4) not null default 0,credit numeric(20,4) not null default 0,foreign key(company_id,journal_entry_id) references public.journal_entries(company_id,id) on delete cascade,foreign key(company_id,account_id) references public.accounts(company_id,id),foreign key(company_id,cost_center_id) references public.cost_centers(company_id,id),check(debit>=0 and credit>=0 and ((debit>0 and credit=0) or (credit>0 and debit=0))));
create table if not exists public.sales_invoices(id uuid primary key default gen_random_uuid(),company_id uuid not null,branch_id uuid not null,invoice_no text not null,customer_id uuid,shift_id uuid,invoice_date timestamptz not null default now(),status text not null default 'draft' check(status in ('draft','posted','void','returned')),subtotal numeric(20,4) not null default 0,discount_total numeric(20,4) not null default 0,tax_total numeric(20,4) not null default 0,grand_total numeric(20,4) not null default 0,created_by uuid references auth.users(id),unique(company_id,id),unique(company_id,branch_id,invoice_no),foreign key(company_id,branch_id) references public.branches(company_id,id),foreign key(company_id,customer_id) references public.parties(company_id,id),foreign key(company_id,shift_id) references public.pos_shifts(company_id,id));
create table if not exists public.sales_invoice_lines(id uuid primary key default gen_random_uuid(),company_id uuid not null,invoice_id uuid not null,product_id uuid not null,description text not null,quantity numeric(20,4) not null check(quantity>0),unit_price numeric(20,4) not null check(unit_price>=0),discount_amount numeric(20,4) not null default 0,tax_amount numeric(20,4) not null default 0,line_total numeric(20,4) not null,foreign key(company_id,invoice_id) references public.sales_invoices(company_id,id) on delete cascade,foreign key(company_id,product_id) references public.products(company_id,id));
create table if not exists public.sales_payments(id uuid primary key default gen_random_uuid(),company_id uuid not null,invoice_id uuid not null,payment_method_id uuid not null,amount numeric(20,4) not null check(amount>0),foreign key(company_id,invoice_id) references public.sales_invoices(company_id,id) on delete cascade,foreign key(company_id,payment_method_id) references public.payment_methods(company_id,id));
create table if not exists public.audit_log(id bigint generated always as identity primary key,company_id uuid not null references public.companies(id),actor_id uuid references auth.users(id),action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.is_company_member(p_company_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.company_members m where m.company_id=p_company_id and m.user_id=auth.uid() and m.is_active) $$;
create or replace function public.has_company_role(p_company_id uuid,p_roles text[]) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.company_members m where m.company_id=p_company_id and m.user_id=auth.uid() and m.is_active and m.role=any(p_roles)) $$;
revoke all on function public.is_company_member(uuid) from public; revoke all on function public.has_company_role(uuid,text[]) from public;
grant execute on function public.is_company_member(uuid) to authenticated; grant execute on function public.has_company_role(uuid,text[]) to authenticated;
do $$ declare t text; begin foreach t in array array['branches','cost_centers','fiscal_periods','accounts','parties','units','products','warehouses','inventory_movements','cash_drawers','payment_methods','pos_shifts','journal_entries','journal_lines','sales_invoices','sales_invoice_lines','sales_payments','audit_log'] loop
execute format('alter table public.%I enable row level security',t);
execute format('create policy %I on public.%I for select to authenticated using(public.is_company_member(company_id))',t||'_select_member',t);
execute format('create policy %I on public.%I for insert to authenticated with check(public.has_company_role(company_id,array[''owner'',''admin'',''accountant'',''supervisor'',''cashier'',''staff'']))',t||'_insert_role',t);
execute format('create policy %I on public.%I for update to authenticated using(public.has_company_role(company_id,array[''owner'',''admin'',''accountant'',''supervisor''])) with check(public.has_company_role(company_id,array[''owner'',''admin'',''accountant'',''supervisor'']))',t||'_update_role',t);
execute format('create policy %I on public.%I for delete to authenticated using(public.has_company_role(company_id,array[''owner'',''admin'']))',t||'_delete_role',t); end loop; end $$;
alter table public.companies enable row level security;
create policy companies_select_member on public.companies for select to authenticated using(public.is_company_member(id));
create policy companies_insert_creator on public.companies for insert to authenticated with check(created_by=auth.uid());
create policy companies_update_admin on public.companies for update to authenticated using(public.has_company_role(id,array['owner','admin'])) with check(public.has_company_role(id,array['owner','admin']));
alter table public.company_members enable row level security;
create policy members_select_self_admin on public.company_members for select to authenticated using(user_id=auth.uid() or public.has_company_role(company_id,array['owner','admin']));
create policy members_insert_admin on public.company_members for insert to authenticated with check(public.has_company_role(company_id,array['owner','admin']) or (user_id=auth.uid() and role='owner'));
create policy members_update_admin on public.company_members for update to authenticated using(public.has_company_role(company_id,array['owner','admin'])) with check(public.has_company_role(company_id,array['owner','admin']));
create policy members_delete_admin on public.company_members for delete to authenticated using(public.has_company_role(company_id,array['owner','admin']));
commit;